// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Paroki) predicate.Paroki {
	return predicate.Paroki(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Paroki) predicate.Paroki {
	return predicate.Paroki(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Paroki) predicate.Paroki {
	return predicate.Paroki(sql.NotPredicates(p))
}
